const campaignId = String($input.first().json.campaignId ?? '').trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(campaignId)) throw new Error('Set campaignId to the UUID from your OutreachGenie campaign URL before running.');
return [{ json: { campaignId: campaignId.toLowerCase(), startedAt: new Date().toISOString() } }];

// This source is embedded in the downloadable workflow by build-workflow.mjs.
function unwrapMcp(node, label) {
  let wrapper = node?.structuredContent;
  if (!wrapper) {
    const text = node?.content?.find((part) => part.type === 'text')?.text;
    try { wrapper = typeof text === 'string' ? JSON.parse(text) : text; }
    catch { throw new Error(`${label}: invalid MCP JSON response.`); }
  }
  if (!wrapper || typeof wrapper !== 'object' || !wrapper.result || typeof wrapper.result !== 'object') {
    throw new Error(`${label}: expected OutreachGenie MCP result wrapper.`);
  }
  return wrapper.result;
}

function buildReview(config, campaign, activity, upcoming, completedAt) {
  const fail = (message) => { throw new Error(`Review stopped: ${message}`); };
  const integer = (value) => Number.isSafeInteger(value) && value >= 0;
  const timestamp = (value) => typeof value === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(value) && Number.isFinite(Date.parse(value));
  const safeText = (value) => String(value).replace(/[\r\n\t]/g, ' ').replace(/[&<>"'\\`*_{}\[\]()#+.!|~-]/g, (character) => `&#${character.charCodeAt(0)};`);
  if (!timestamp(config.startedAt) || !timestamp(completedAt)) fail('capture timestamps are invalid.');
  if (campaign.id !== config.campaignId || typeof campaign.name !== 'string' || typeof campaign.status !== 'string') fail('campaign identity or state does not match the selected campaign.');
  const metricNames = ['actions_run_count', 'actions_completed_count', 'actions_failed_count', 'actions_skipped_count', 'actions_waiting_count', 'actions_remaining_count', 'connection_requests_sent_count', 'connection_requests_accepted_count', 'replies_count', 'reply_tracked_prospect_count'];
  const metrics = {};
  for (const name of metricNames) {
    if (!integer(campaign.overview?.[name])) fail(`missing or invalid current overview field: ${name}.`);
    metrics[name] = campaign.overview[name];
  }
  for (const name of ['connection_request_acceptance_rate', 'reply_rate']) {
    const value = campaign.overview?.[name];
    if (value !== null && (!integer(value) || value > 100)) fail(`missing or invalid current overview field: ${name}.`);
    metrics[name] = value;
  }
  function page(payload, label) {
    const p = payload?.pagination;
    if (!Array.isArray(payload?.items) || !p || typeof p !== 'object' || Array.isArray(p)) fail(`${label}: missing pagination schema.`);
    const nativeKeys = ['currentPage', 'pageSize', 'totalCount', 'hasNextPage'];
    const normalizedKeys = ['page', 'page_size', 'total', 'has_more', 'next_page'];
    const hasNative = nativeKeys.some((key) => Object.hasOwn(p, key));
    const hasNormalized = normalizedKeys.some((key) => Object.hasOwn(p, key));
    if (!hasNative && !hasNormalized) fail(`${label}: unexpected pagination schema.`);
    if (hasNative && !nativeKeys.every((key) => Object.hasOwn(p, key))) fail(`${label}: incomplete native pagination fields.`);
    if (hasNormalized && !normalizedKeys.every((key) => Object.hasOwn(p, key))) fail(`${label}: incomplete normalized pagination fields.`);
    const currentPage = hasNative ? p.currentPage : p.page;
    const pageSize = hasNative ? p.pageSize : p.page_size;
    const total = hasNative ? p.totalCount : p.total;
    const hasMore = hasNative ? p.hasNextPage : p.has_more;
    if (currentPage !== 1 || pageSize !== 50 || !integer(total) || typeof hasMore !== 'boolean') fail(`${label}: unexpected first-page pagination values.`);
    const length = payload.items.length;
    if (length !== Math.min(50, total) || hasMore !== (total > length)) fail(`${label}: inconsistent first-page counts; no report was generated.`);
    if (hasNormalized) {
      for (const [key, expected] of [['page', currentPage], ['page_size', pageSize], ['total', total], ['has_more', hasMore], ['next_page', hasMore ? 2 : null]]) {
        if (p[key] !== expected) fail(`${label}: normalized pagination fields disagree.`);
      }
    }
    for (const [key, expected] of [['totalPages', Math.max(1, Math.ceil(total / 50))], ['startIndex', total ? 1 : 0], ['endIndex', length], ['hasPreviousPage', false], ['previous_page', null]]) {
      if (Object.hasOwn(p, key) && p[key] !== expected) fail(`${label}: pagination metadata is inconsistent.`);
    }
    return { returned: length, availableAtFetch: total, incomplete: hasMore, page: 1, pageSize: 50 };
  }
  const activityCoverage = page(activity, 'Activity');
  const upcomingCoverage = page(upcoming, 'Upcoming actions');
  const outcomes = { completed: 0, failed: 0, skipped: 0, waiting: 0, pending: 0, running: 0, other: 0 };
  const states = { queued: 0, scheduled: 0, on_hold: 0, blocked: 0 };
  const activityTimes = [];
  for (const row of activity.items) {
    if (!row || !timestamp(row.recorded_at) || typeof row.outcome !== 'string') fail('activity row has an invalid recorded time or outcome.');
    outcomes[Object.hasOwn(outcomes, row.outcome) ? row.outcome : 'other'] += 1;
    activityTimes.push(new Date(row.recorded_at).toISOString());
  }
  const scheduledTimes = [];
  let unscheduled = 0;
  for (const row of upcoming.items) {
    if (!row || !Object.hasOwn(states, row.schedule_state)) fail('upcoming row has an unsupported schedule state.');
    states[row.schedule_state] += 1;
    if (row.scheduled_at === null) unscheduled += 1;
    else if (timestamp(row.scheduled_at)) scheduledTimes.push(new Date(row.scheduled_at).toISOString());
    else fail('upcoming row has an invalid projected time.');
  }
  activityTimes.sort(); scheduledTimes.sort();
  const range = (values) => values.length ? { earliest: values[0], latest: values.at(-1) } : null;
  const report = {
    schemaVersion: 1,
    campaign: { id: campaign.id, name: campaign.name, status: campaign.status },
    capture: { startedAt: config.startedAt, completedAt, atomic: false },
    currentRecordedOverview: metrics,
    recentActivityFirstPage: { coverage: activityCoverage, outcomes, recordedRange: range(activityTimes) },
    upcomingFirstPage: { coverage: upcomingCoverage, scheduleStates: states, projectedRange: range(scheduledTimes), withoutProjectedTime: unscheduled },
  };
  const showRange = (value) => value ? `${value.earliest} to ${value.latest}` : 'None returned';
  const coverageLine = (coverage) => `${coverage.returned} returned of ${coverage.availableAtFetch} available at that fetch. Page 1 only (limit 50). ${coverage.incomplete ? 'INCOMPLETE: additional pages were not fetched.' : 'All rows available at that fetch were returned.'}`;
  const table = (entries) => ['| Recorded field | Value |', '| --- | --- |', ...entries.map(([key, value]) => `| ${safeText(key)} | ${value === null ? 'Unavailable' : value} |`)].join('\n');
  const markdown = [
    '# OutreachGenie campaign review',
    `Campaign: **${safeText(campaign.name)}**`, `Campaign ID: ${campaign.id}`, `Current state: ${safeText(campaign.status)}`,
    `Capture started: ${config.startedAt}`, `Capture completed: ${completedAt}`,
    'The three read calls run sequentially. This is a current snapshot, not an atomic snapshot or a period-performance report.',
    '## Current recorded overview',
    'These are stored campaign values at the campaign fetch, not counts for the activity page below. Recorded action totals count events, not unique people. Remaining actions count remaining flow action nodes in unfinished executions; they are not sent events or guaranteed future sends. Rates are percentages supplied by OutreachGenie; an unavailable rate is not zero.',
    table(Object.entries(metrics)),
    'Reply rate uses the tracked-prospect denominator. Connection acceptance uses recorded connection requests. Neither measures meetings, revenue or ROI.',
    '## Recent activity: first page', coverageLine(activityCoverage),
    `Recorded timestamp range among returned rows: ${showRange(report.recentActivityFirstPage.recordedRange)}.`,
    'The service returns newest activity first. Counts below describe only these returned events; no date filter was applied.', table(Object.entries(outcomes)),
    '## Upcoming actions: first page', coverageLine(upcomingCoverage), table(Object.entries(states)),
    `Projected timestamp range among returned rows with a time: ${showRange(report.upcomingFirstPage.projectedRange)}.`,
    `Returned rows without a projected time: ${unscheduled}.`,
    'Upcoming means pending/waiting tasks on pending/waiting executions. It excludes other in-flight work and later steps that do not yet have tasks. Projected times are estimates; reading this report does not schedule or send anything. On-hold and blocked work needs review in OutreachGenie.',
    '## Handling this report',
    'The report omits prospect names, profile URLs, message bodies and individual activity details. It includes the chosen campaign name and aggregate business data: review it before sharing. Raw MCP node responses can contain personal data and remain visible during execution. Workflow persistence settings reduce saved execution data but do not replace your n8n access, logging, backup and retention policies.',
    'No messages were sent and no campaign state was changed by this workflow.',
  ].join('\n\n');
  return { report, markdown, fileName: `outreachgenie-campaign-review-${campaign.id}.md` };
}

const result = buildReview($('Validate Campaign').first().json, unwrapMcp($('Read Campaign').first().json, 'Campaign'), unwrapMcp($('Read Recent Activity').first().json, 'Activity'), unwrapMcp($('Read Upcoming Actions').first().json, 'Upcoming'), new Date().toISOString());
return [{ json: result }];
